1	import type { LoadedAssets } from './assets.js';
2	import type { BlockRegistry, BlockDef } from './blocks.js';
3	import type { World } from './world.js';
4	import type { Player } from './player.js';
5	import type { Renderer } from './renderer.js';
6	import { clamp } from './math.js';
7	
8	const COLORS = {
9	  white: '#ffffff',
10	  gray: '#aaaaaa',
11	  darkGray: '#555555',
12	  yellow: '#ffff55',
13	  green: '#55ff55',
14	  red: '#ff5555',
15	  aqua: '#55ffff',
16	};
17	
18	function titleCase(s: string): string {
19	  return s.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
20	}
