22	export class Hud {
23	  private ctx: CanvasRenderingContext2D;
24	  private scale = 3;
25	  private guiW = 640;
26	  private guiH = 360;
27	  private icons = new Map<number, HTMLCanvasElement>();
28	  private iconCache = new Map<string, HTMLCanvasElement>();
29	  private underwaterPattern: CanvasPattern | null = null;
30	  inventoryOpen = false;
31	  inventoryPage = 0;
32	  private noticeText = '';
33	  private noticeUntil = 0;
34	  private mouseCss = { x: 0, y: 0 };
35	  private invBlocks: BlockDef[];
36	
37	  constructor(private canvas: HTMLCanvasElement, private assets: LoadedAssets, private rocks: BlockRegistry, private world: World) {
38	    const ctx = canvas.getContext('2d')!;
39	    ctx.imageSmoothingEnabled = false;
40	    this.ctx = ctx;
41	    this.invBlocks = rocks.blocks.filter(b => b.id > 0);
42	    try {
43	      this.underwaterPattern = ctx.createPattern(assets.env.underwater, 'repeat');
44	    } catch { /* ignore */ }
45	  }
46	
47	  resize(cssW: number, cssH: number): void {
48	    this.scale = clamp(Math.floor(Math.min(cssW / 320, cssH / 240)), 2, 4);
49	    this.guiW = Math.ceil(cssW / this.scale);
50	    this.guiH = Math.ceil(cssH / this.scale);
51	    this.canvas.width = this.guiW;
52	    this.canvas.height = this.guiH;
53	    this.canvas.style.width = cssW + 'px';
54	    this.canvas.style.height = cssH + 'px';
55	    this.ctx.imageSmoothingEnabled = false;
56	  }
57	
58	  private tinted(key: string, color: string): HTMLCanvasElement | null {
59	    const cacheKey = key + '|' + color;
60	    const cached = this.iconCache.get(cacheKey);
61	    if (cached) return cached;
62	    const img = this.assets.icons.get(key);
63	    if (!img) return null;
64	    const c = document.createElement('canvas');
65	    c.width = img.width;
66	    c.height = img.height;
67	    const ctx = c.getContext('2d')!;
68	    ctx.imageSmoothingEnabled = false;
69	    ctx.drawImage(img, 0, 0);
70	    ctx.globalCompositeOperation = 'multiply';
71	    ctx.fillStyle = color;
72	    ctx.fillRect(0, 0, c.width, c.height);
73	    this.iconCache.set(cacheKey, c);
74	    return c;
75	  }
76	
77	  private blockIcon(def: BlockDef): HTMLCanvasElement {
78	    const cached = this.icons.get(def.id);
79	    if (cached) return cached;
80	    const c = document.createElement('canvas');
81	    c.width = 32;
82	    c.height = 32;
83	    const ctx = c.getContext('2d')!;
84	    ctx.imageSmoothingEnabled = false;
85	    const tint = def.name === 'grass_block' ? '#91bd59' :
86	      def.name === 'oak_leaves' ? '#77ab2f' :
87	        def.name === 'birch_leaves' ? '#80a755' :
88	          def.name === 'spruce_leaves' ? '#619961' : null;
89	    const top = def.iconTop ? (tint ? this.tinted(def.iconTop, tint) : this.assets.icons.get(def.iconTop)) : null;
90	    const side = def.iconSide ? (tint ? this.tinted(def.iconSide, tint) : this.assets.icons.get(def.iconSide)) : null;
91	    const flat = ['short_grass', 'fern', 'dead_bush', 'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy',
92	      'allium', 'lily_of_the_valley', 'torch', 'lantern', 'cactus', 'sulfur_spike', 'water', 'lava'].includes(def.name);
93	    const cube = !flat && !!top && !!side;
94	    if (cube && top && side) {
95	      ctx.save();
96	      ctx.setTransform(1, 0.5, -1, 0.5, 16, 0);
97	      ctx.drawImage(top as CanvasImageSource, 0, 0);
98	      ctx.restore();
99	      ctx.save();
100	      ctx.filter = 'brightness(80%)';
101	      ctx.setTransform(1, 0.5, 0, 1, 0, 8);
102	      ctx.drawImage(side as CanvasImageSource, 0, 0);
103	      ctx.restore();
104	      ctx.save();
105	      ctx.filter = 'brightness(60%)';
106	      ctx.setTransform(1, -0.5, 0, 1, 16, 16);
107	      ctx.drawImage(side as CanvasImageSource, 0, 0);
108	      ctx.restore();
109	    } else {
110	      const flatImg = this.assets.icons.get(def.iconFlat ?? '');
111	      if (flatImg) ctx.drawImage(flatImg, 0, 0, 32, 32);
112	      else if (top) ctx.drawImage(top as CanvasImageSource, 0, 0, 32, 32);
113	    }
114	    this.icons.set(def.id, c);
115	    return c;
116	  }
117	
118	  setInventory(open: boolean, page?: number): void {
119	    this.inventoryOpen = open;
120	    if (open && page != null) this.inventoryPage = page;
121	  }
122	
123	  setMouse(cssX: number, cssY: number): void {
124	    this.mouseCss.x = cssX;
125	    this.mouseCss.y = cssY;
126	  }
127	
128	  toast(text: string): void {
129	    this.noticeText = text;
130	    this.noticeUntil = performance.now() + 1600;
131	  }
132	
133	  private invLayout() {
134	    const cols = 9, rows = 5, slot = 18, pad = 8, header = 22, footer = 14;
135	    const w = cols * slot + pad * 2;
136	    const h = rows * slot + header + footer;
137	    const x = Math.floor((this.guiW - w) / 2);
138	    const y = Math.floor((this.guiH - h) / 2);
139	    return { cols, rows, slot, pad, header, footer, w, h, x, y };
140	  }
141	
142	  private invIndexAt(gx: number, gy: number): number {
143	    const L = this.invLayout();
144	    const gridX = L.x + L.pad, gridY = L.y + L.header;
145	    if (gx < gridX || gy < gridY) return -1;
146	    const col = Math.floor((gx - gridX) / L.slot);
147	    const row = Math.floor((gy - gridY) / L.slot);
148	    if (col < 0 || col >= L.cols || row < 0 || row >= L.rows) return -1;
149	    const idx = this.inventoryPage * L.cols * L.rows + row * L.cols + col;
150	    return idx < this.invBlocks.length ? idx : -1;
151	  }
152	
153	  inventoryHit(cssX: number, cssY: number): { page: number } | { block: number } | null {
154	    if (!this.inventoryOpen) return null;
155	    const gx = cssX / this.scale, gy = cssY / this.scale;
156	    const L = this.invLayout();
157	    const pages = Math.max(1, Math.ceil(this.invBlocks.length / (L.cols * L.rows)));
158	    const arrowY = L.y + 6;
159	    if (gx >= L.x + L.w - 30 && gx <= L.x + L.w - 18 && gy >= arrowY && gy <= arrowY + 10) return { page: -1 };
160	    if (gx >= L.x + L.w - 16 && gx <= L.x + L.w - 4 && gy >= arrowY && gy <= arrowY + 10) return { page: 1 };
161	    if (pages <= 1) { /* no-op */ }
162	    const idx = this.invIndexAt(gx, gy);
163	    if (idx >= 0) return { block: this.invBlocks[idx].id };
164	    return null;
165	  }
166	
167	  private drawInventory(): void {
168	    const { ctx, assets } = this;
169	    const L = this.invLayout();
170	    const pages = Math.max(1, Math.ceil(this.invBlocks.length / (L.cols * L.rows)));
171	    if (this.inventoryPage >= pages) this.inventoryPage = pages - 1;
172	    if (this.inventoryPage < 0) this.inventoryPage = 0;
173	    // panel
174	    ctx.fillStyle = '#c6c6c6';
175	    ctx.fillRect(L.x, L.y, L.w, L.h);
176	    ctx.fillStyle = '#ffffff';
177	    ctx.fillRect(L.x, L.y, L.w, 2);
178	    ctx.fillRect(L.x, L.y, 2, L.h);
179	    ctx.fillStyle = '#555555';
180	    ctx.fillRect(L.x, L.y + L.h - 2, L.w, 2);
181	    ctx.fillRect(L.x + L.w - 2, L.y, 2, L.h);
182	    ctx.fillStyle = '#8b8b8b';
183	    ctx.fillRect(L.x + L.pad, L.y + L.header - 2, L.w - L.pad * 2, L.h - L.header - L.footer + 2);
184	    // title
185	    assets.font.draw(ctx, 'Creative Blocks', L.x + L.pad, L.y + 7, '#3f3f3f', false);
186	    const pageLabel = `${this.inventoryPage + 1}/${pages}`;
187	    assets.font.draw(ctx, pageLabel, L.x + L.w - L.pad - assets.font.width(pageLabel) - 28, L.y + 7, '#3f3f3f', false);
188	    assets.font.draw(ctx, '<', L.x + L.w - 28, L.y + 7, '#3f3f3f', false);
189	    assets.font.draw(ctx, '>', L.x + L.w - 14, L.y + 7, '#3f3f3f', false);
190	    // slots
191	    const gx = this.mouseCss.x / this.scale;
192	    const gy = this.mouseCss.y / this.scale;
193	    const hover = this.invIndexAt(gx, gy);
194	    const gridX = L.x + L.pad, gridY = L.y + L.header;
195	    const perPage = L.cols * L.rows;
196	    for (let i = 0; i < perPage; i++) {
197	      const idx = this.inventoryPage * perPage + i;
198	      const col = i % L.cols, row = (i / L.cols) | 0;
199	      const sx = gridX + col * L.slot, sy = gridY + row * L.slot;
200	      ctx.fillStyle = '#8b8b8b';
201	      ctx.fillRect(sx, sy, 18, 18);
202	      ctx.fillStyle = '#373737';
203	      ctx.fillRect(sx, sy, 18, 1);
204	      ctx.fillRect(sx, sy, 1, 18);
205	      ctx.fillStyle = '#ffffff';
206	      ctx.fillRect(sx, sy + 17, 18, 1);
207	      ctx.fillRect(sx + 17, sy, 1, 18);
208	      if (idx >= this.invBlocks.length) continue;
209	      const def = this.invBlocks[idx];
210	      if (idx === hover) {
211	        ctx.fillStyle = 'rgba(255,255,255,0.85)';
212	        ctx.fillRect(sx + 1, sy + 1, 16, 16);
213	      }
214	      const icon = this.blockIcon(def);
215	      ctx.drawImage(icon, sx + 1, sy + 1, 16, 16);
216	    }
217	    // tooltip / hints
218	    let hint = 'E to close';
219	    if (hover >= 0) hint = titleCase(this.invBlocks[hover].name);
220	    assets.font.draw(ctx, hint, L.x + L.pad, L.y + L.h - 11, '#3f3f3f', false);
221	  }
222	
223	  render(state: {
224	    started: boolean;
225	    paused: boolean;
226	    player: Player;
227	    fps: number;
228	    ticks: number;
229	    debug: boolean;
230	    underwater: boolean;
231	    renderer: Renderer;
232	    elapsed: number;
233	    inventoryOpen: boolean;
234	  }): void {
235	    const { ctx, guiW, guiH } = this;
236	    ctx.clearRect(0, 0, guiW, guiH);
237	    const player = state.player;
238	
239	    if (state.underwater) {
240	      if (this.underwaterPattern) {
241	        ctx.save();
242	        ctx.globalAlpha = 0.35;
243	        ctx.fillStyle = this.underwaterPattern;
244	        ctx.fillRect(0, 0, guiW, guiH);
245	        ctx.restore();
246	      }
247	      ctx.fillStyle = 'rgba(20,60,140,0.18)';
248	      ctx.fillRect(0, 0, guiW, guiH);
249	    }
250	
251	    if (!state.started) {
252	      this.drawTitle(false);
253	      return;
254	    }
255	
256	    const hotbarX = Math.floor((guiW - 182) / 2);
257	    const hotbarY = guiH - 22;
258	    ctx.drawImage(this.assets.gui.hotbar, hotbarX, hotbarY);
259	    ctx.drawImage(this.assets.gui.hotbarSelection, hotbarX - 1 + player.selected * 20, hotbarY - 1);
260	    for (let i = 0; i < 9; i++) {
261	      const def = player.hotbar[i];
262	      if (!def) continue;
263	      const icon = this.blockIcon(def);
264	      ctx.drawImage(icon, hotbarX + 3 + i * 20, hotbarY + 3, 16, 16);
265	    }
266	
267	    if (!state.inventoryOpen) {
268	      ctx.drawImage(this.assets.gui.crosshair, Math.floor((guiW - 15) / 2), Math.floor((guiH - 15) / 2));
269	    }
270	
271	    const now = performance.now();
272	    if (now - player.selectedSince < 2200) {
273	      const def = player.currentBlock();
274	      if (def) {
275	        const name = titleCase(def.name);
276	        this.assets.font.drawCentered(ctx, name, guiW / 2, hotbarY - 18, COLORS.white, true);
277	      }
278	    }
279	
280	    if (performance.now() < this.noticeUntil && !state.inventoryOpen) {
281	      this.assets.font.drawCentered(ctx, this.noticeText, guiW / 2, 12, COLORS.white, true);
282	    }
283	    if (state.inventoryOpen) this.drawInventory();
284	    if (state.debug) this.drawDebug(state);
285	    if (state.paused && !state.inventoryOpen) this.drawTitle(true);
286	  }
287	
288	  private drawTitle(paused: boolean): void {
289	    const { ctx, guiW, guiH, assets } = this;
290	    ctx.fillStyle = 'rgba(0,0,0,0.62)';
291	    ctx.fillRect(0, 0, guiW, guiH);
292	    const logo = assets.gui.title;
293	    if (logo) {
294	      const w = 256, h = 64;
295	      ctx.drawImage(logo, Math.floor((guiW - w) / 2), 28, w, h);
296	    }
297	    assets.font.drawCentered(ctx, 'Java Edition 26.2 · Vanilla assets · WebGL2', guiW / 2, 100, COLORS.gray, true);
298	    const bw = 200, bh = 20;
299	    const bx = Math.floor((guiW - bw) / 2), by = 126;
300	    const btn = paused ? (assets.gui.buttonHighlighted ?? assets.gui.button) : assets.gui.button;
301	    if (btn) ctx.drawImage(btn, bx, by, bw, bh);
302	    else { ctx.fillStyle = '#6f6f6f'; ctx.fillRect(bx, by, bw, bh); }
303	    assets.font.drawCentered(ctx, paused ? 'Resume' : 'Play', guiW / 2, by + 6, COLORS.white, true);
304	
305	    const lines = [
306	      'WASD Move    Space Jump / double-tap to Fly    Shift Descend / Sneak',
307	      'Ctrl Sprint    F Toggle flight    F3 Debug    N Noon    M Midnight',
308	      'Left click Break    Right click Place    Middle click Pick    Wheel/1-9 Hotbar',
309	      'E Creative blocks    V Mipmap    T Freeze time',
310	      '',
311	      'Click to lock the mouse. ESC releases it.',
312	      'Textures, models, sounds and font come from your own Minecraft 26.2 client.',
313	    ];
314	    let y = 164;
315	    for (const line of lines) {
316	      assets.font.drawCentered(ctx, line, guiW / 2, y, y > 210 ? COLORS.darkGray : COLORS.gray, true);
317	      y += 10;
318	    }
319	    assets.font.drawCentered(ctx, 'Chaos Cubed · sulfur & cinnabar included', guiW / 2, guiH - 18, COLORS.darkGray, false);
320	  }
321	
322	  private drawDebug(state: {
323	    player: Player; fps: number; ticks: number; renderer: Renderer;
324	  }): void {
325	    const { ctx, assets } = this;
326	    const p = state.player;
327	    const eye = p.eye();
328	    const bx = Math.floor(eye.x), by = Math.floor(eye.y), bz = Math.floor(eye.z);
329	    const total = ((state.ticks % 24000) + 24000) % 24000;
330	    const hours = ((total / 1000 + 6) % 24);
331	    const hh = Math.floor(hours).toString().padStart(2, '0');
332	    const mm = Math.floor((hours % 1) * 60).toString().padStart(2, '0');
333	    const yawDeg = ((p.yaw * 180 / Math.PI) % 360 + 360) % 360;
334	    const dirs = [[0, 'south (+Z)'], [90, 'west (-X)'], [180, 'north (-Z)'], [270, 'east (+X)']];
335	    let facing = dirs[0][1] as string;
336	    for (let i = 0; i < 4; i++) {
337	      const a = dirs[i][0] as number;
338	      const b = (dirs[(i + 1) % 4][0] as number) + (i === 3 ? 360 : 0);
339	      if (yawDeg >= a && yawDeg < b) facing = dirs[i][1] as string;
340	    }
341	    const target = p.target;
342	    const targetId = target ? this.world.getBlock(target.x, target.y, target.z) : 0;
343	    const targetDef = this.rocks.get(targetId);
344	    const lightS = this.world.getSky(bx, by, bz);
345	    const lightB = this.world.getBlockLight(bx, by, bz);
346	    const stats = state.renderer.drawStats;
347	    const lines = [
348	      ['Minecraft 26.2 · WebGL2 fan renderer', COLORS.white],
349	      [`FPS ${state.fps.toFixed(0)}   draw calls ${stats.chunks + stats.translucent}   tris ${(stats.triangles / 1000).toFixed(1)}k`, COLORS.gray],
350	      [`XYZ ${p.pos.x.toFixed(3)} / ${p.pos.y.toFixed(3)} / ${p.pos.z.toFixed(3)}`, COLORS.white],
351	      [`Block ${bx} ${by} ${bz}   Chunk ${bx >> 4} ${bz >> 4}`, COLORS.gray],
352	      [`Facing ${facing}  (yaw ${yawDeg.toFixed(1)}°)`, COLORS.white],
353	      [`Biome ${this.world.biomeNameAt(bx, bz)}   Light sky ${lightS} block ${lightB}`, COLORS.gray],
354	      [`Time ${hh}:${mm} (${total} ticks)   ${p.flying ? 'flying' : 'walking'}`, COLORS.white],
355	      [`Target ${target ? targetDef.name : 'none'}`, COLORS.gray],
356	      [`Seed ${this.world.seed}   Dist 6   ${p.locked ? 'mouse locked' : 'mouse free'}`, COLORS.darkGray],
357	    ];
358	    let w = 0;
359	    for (const [line] of lines) w = Math.max(w, assets.font.width(line as string));
360	    ctx.fillStyle = 'rgba(0,0,0,0.38)';
361	    ctx.fillRect(1, 1, w + 5, lines.length * 9 + 5);
362	    let y = 4;
363	    for (const [line, color] of lines) {
364	      assets.font.draw(ctx, line as string, 4, y, color as string, true);
365	      y += 9;
366	    }
367	  }
368	}
