1	import { loadBitmap } from './gl.js';
2	import { VanillaFont } from './font.js';
3	import type { Manifest, TextureInfo } from './types.js';
4	
5	const BASE = '/mc/';
6	
7	export interface LoadedAssets {
8	  manifest: Manifest;
9	  texArray: WebGLTexture;
10	  icons: Map<string, ImageBitmap>;
11	  gui: Record<string, ImageBitmap>;
12	  env: Record<string, ImageBitmap>;
13	  font: VanillaFont;
14	  grassColormap: ImageData;
15	  foliageColormap: ImageData;
16	}
17	
18	export type ProgressFn = (fraction: number, label: string) => void;
