22	class Builder {
23	  data = new Float32Array(1 << 16);
24	  len = 0;
25	  indices = new Uint32Array(1 << 15);
26	  indexCount = 0;
27	
28	  ensure(n: number) {
29	    if (this.len + n <= this.data.length) return;
30	    let size = this.data.length;
31	    while (size < this.len + n) size *= 2;
32	    const next = new Float32Array(size);
33	    next.set(this.data.subarray(0, this.len));
34	    this.data = next;
35	  }
36	
37	  ensureIndices(n: number) {
38	    if (this.indexCount + n <= this.indices.length) return;
39	    let size = this.indices.length;
40	    while (size < this.indexCount + n) size *= 2;
41	    const next = new Uint32Array(size);
42	    next.set(this.indices.subarray(0, this.indexCount));
43	    this.indices = next;
44	  }
45	
46	  vertex(px: number, py: number, pz: number, u: number, v: number, layer: number, anim: number,
47	    sky: number, block: number, ao: number, tr: number, tg: number, tb: number, shade: number,
48	    nx: number, ny: number, nz: number) {
49	    const d = this.data;
50	    let o = this.len;
51	    d[o++] = px; d[o++] = py; d[o++] = pz;
52	    d[o++] = u; d[o++] = v;
53	    d[o++] = layer; d[o++] = anim;
54	    d[o++] = sky; d[o++] = block; d[o++] = ao;
55	    d[o++] = tr; d[o++] = tg; d[o++] = tb;
56	    d[o++] = shade;
57	    d[o++] = nx; d[o++] = ny; d[o++] = nz;
58	    this.len = o;
59	  }
60	
61	  quad(): number {
62	    const base = this.len / STRIDE;
63	    this.ensureIndices(6);
64	    const idx = this.indices;
65	    let o = this.indexCount;
66	    idx[o++] = base; idx[o++] = base + 1; idx[o++] = base + 2;
67	    idx[o++] = base; idx[o++] = base + 2; idx[o++] = base + 3;
68	    this.indexCount = o;
69	    return base;
70	  }
71	}
72	
73	interface CellSample { sky: number; block: number; opaque: boolean; }
74	
75	function readCell(world: World, rocks: BlockRegistry, x: number, y: number, z: number): CellSample {
76	  if (y < WORLD_MIN_Y) return { sky: 0, block: 0, opaque: true };
77	  if (y >= WORLD_MAX_Y) return { sky: 15, block: 0, opaque: false };
78	  const id = world.getBlock(x, y, z);
79	  const def = rocks.get(id);
80	  return {
81	    sky: world.getSky(x, y, z),
82	    block: world.getBlockLight(x, y, z),
83	    opaque: id !== 0 && def.flags ? def.flags.opaque : false,
84	  };
85	}
86	
87	function vertexSample(world: World, rocks: BlockRegistry, x: number, y: number, z: number,
88	  dir: number, px: number, py: number, pz: number, aoEnabled: boolean) {
89	  const [nx, ny, nz] = DIRS[dir];
90	  let ux = 0, uy = 0, uz = 0, vx = 0, vy = 0, vz = 0;
91	  let coordU = 0, coordV = 0;
92	  if (dir === 0 || dir === 1) {
93	    ux = 1; vz = 1; coordU = px; coordV = pz;
94	  } else if (dir === 2 || dir === 3) {
95	    ux = 1; vy = 1; coordU = px; coordV = py;
96	  } else {
97	    uz = 1; vy = 1; coordU = pz; coordV = py;
98	  }
99	  const su = coordU >= 0.5 ? 1 : -1;
100	  const sv = coordV >= 0.5 ? 1 : -1;
101	  const fx = x + nx, fy = y + ny, fz = z + nz;
102	  const center = readCell(world, rocks, fx, fy, fz);
103	  if (center.opaque) return { sky: 0, block: 0, ao: aoEnabled ? 0.2 : 1 };
104	
105	  const a = readCell(world, rocks, fx + ux * su, fy + uy * su, fz + uz * su);
106	  const b = readCell(world, rocks, fx + vx * sv, fy + vy * sv, fz + vz * sv);
107	  const d = readCell(world, rocks, fx + ux * su + vx * sv, fy + uy * su + vy * sv, fz + uz * su + vz * sv);
108	
109	  const fix = (s: CellSample, sky: number, block: number) => {
110	    let ss = s.sky, sb = s.block;
111	    if (ss === 0 && center.sky > 2) ss = center.sky;
112	    if (sb === 0 && center.block > 2) sb = center.block;
113	    return [ss, sb];
114	  };
115	  let skySum = center.sky, blockSum = center.block, count = 1;
116	  if (!a.opaque) { const [s, bl] = fix(a, a.sky, a.block); skySum += s; blockSum += bl; count++; }
117	  if (!b.opaque) { const [s, bl] = fix(b, b.sky, b.block); skySum += s; blockSum += bl; count++; }
118	  if (!d.opaque) { const [s, bl] = fix(d, d.sky, d.block); skySum += s; blockSum += bl; count++; }
119	
120	  let ao = 1;
121	  if (aoEnabled) {
122	    const occ = (a.opaque ? 1 : 0) + (b.opaque ? 1 : 0) + (d.opaque ? 1 : 0);
123	    ao = Math.max(0.2, 1 - 0.2 * occ);
124	  }
125	  return { sky: skySum / count / 15, block: blockSum / count / 15, ao };
126	}
127	
128	function tintFor(world: World, def: ReturnType<BlockRegistry['get']>, ti: number, x: number, z: number): [number, number, number] {
129	  if (ti < 0 || def.tintMode === 0) return [1, 1, 1];
130	  if (def.tintMode === 4) return def.tintColor;
131	  return world.tintAt(x, z, def.tintMode, def.tintColor);
132	}
133	
134	function isCulled(world: World, rocks: BlockRegistry, x: number, y: number, z: number, id: number, q: Quad): boolean {
135	  if (q.c < 0) return false;
136	  const [dx, dy, dz] = DIRS[q.c];
137	  const nx = x + dx, ny = y + dy, nz = z + dz;
138	  const nid = world.getBlock(nx, ny, nz);
139	  if (nid === 0) return false;
140	  if (nid === id && rocks.cullSelf[id]) return true;
141	  const nd = rocks.get(nid);
142	  return nd.flags ? nd.flags.opaque : false;
143	}
144	
145	function addStructuredQuad(builder: Builder, world: World, rocks: BlockRegistry, def: ReturnType<BlockRegistry['get']>,
146	  x: number, y: number, z: number, dir: number, positions: number[], uvs: number[], layer: number, anim: number,
147	  tint: [number, number, number], shade: number, aoEnabled: boolean, forceLight: boolean): void {
148	  builder.ensure(STRIDE * 4);
149	  for (let i = 0; i < 4; i++) {
150	    const px = positions[i * 3], py = positions[i * 3 + 1], pz = positions[i * 3 + 2];
151	    let sky = 1, block = 1, ao = 1;
152	    if (!forceLight) {
153	      const sample = vertexSample(world, rocks, x, y, z, dir, px, py, pz, aoEnabled);
154	      sky = sample.sky; block = sample.block; ao = sample.ao;
155	    }
156	    const [nx, ny, nz] = DIRS[dir];
157	    builder.vertex(x + px, y + py, z + pz, uvs[i * 2] / 16, uvs[i * 2 + 1] / 16,
158	      layer, anim, sky, block, ao, tint[0], tint[1], tint[2], shade, nx, ny, nz);
159	  }
160	  builder.quad();
161	}
162	
163	function emitFluid(builder: Builder, world: World, rocks: BlockRegistry, x: number, y: number, z: number,
164	  id: number, def: ReturnType<BlockRegistry['get']>): void {
165	  const aboveSame = world.getBlock(x, y + 1, z) === id;
166	  const top = aboveSame ? 1 : 8 / 9;
167	  const lava = def.custom === 'lava';
168	  const tint: [number, number, number] = lava ? [1, 1, 1] : world.tintAt(x, z, def.tintMode, def.tintColor);
169	  const layer = def.fluidLayer;
170	  const anim = def.fluidAnim;
171	  const forceLight = lava;
172	  const shade = (dir: number) => FACE_SHADE[dir];
173	
174	  const emit = (dir: number, positions: number[], uvs: number[]) => {
175	    if (forceLight) {
176	      addStructuredQuad(builder, world, rocks, def, x, y, z, dir, positions, uvs, layer, anim, tint, 1, true, true);
177	    } else {
178	      const base = builder.len / STRIDE;
179	      for (let i = 0; i < 4; i++) {
180	        const px = positions[i * 3], py = positions[i * 3 + 1], pz = positions[i * 3 + 2];
181	        const sample = vertexSample(world, rocks, x, y, z, dir, px, py, pz, false);
182	        const [nx, ny, nz] = DIRS[dir];
183	        builder.vertex(x + px, y + py, z + pz, uvs[i * 2] / 16, uvs[i * 2 + 1] / 16,
184	          layer, anim, sample.sky, sample.block, 1, tint[0], tint[1], tint[2], shade(dir), nx, ny, nz);
185	      }
186	      builder.quad();
187	    }
188	  };
189	
190	  if (!aboveSame) {
191	    const below = world.getBlock(x, y + 1, z);
192	    if (!rocks.get(below).flags?.opaque) {
193	      emit(1, [0, top, 0, 0, top, 1, 1, top, 1, 1, top, 0], [0, 0, 0, 16, 16, 16, 16, 0]);
194	    }
195	  }
196	  const sideDirs: [number, number][] = [[2, 0], [3, 0], [4, 0], [5, 0]];
197	  for (const [dir] of sideDirs) {
198	    const [dx, , dz] = DIRS[dir];
199	    const nid = world.getBlock(x + dx, y, z + dz);
200	    if (nid === id) continue;
201	    if (rocks.get(nid).flags?.opaque) continue;
202	    let positions: number[];
203	    if (dir === 2) positions = [1, top, 0, 1, 0, 0, 0, 0, 0, 0, top, 0];
204	    else if (dir === 3) positions = [0, top, 1, 0, 0, 1, 1, 0, 1, 1, top, 1];
205	    else if (dir === 4) positions = [0, top, 0, 0, 0, 0, 0, 0, 1, 0, top, 1];
206	    else positions = [1, top, 1, 1, 0, 1, 1, 0, 0, 1, top, 0];
207	    emit(dir, positions, [0, 0, 0, 16, 16, 16, 16, 0]);
208	  }
209	  const belowId = world.getBlock(x, y - 1, z);
210	  if (belowId !== id && !rocks.get(belowId).flags?.opaque) {
211	    emit(0, [0, 0, 1, 0, 0, 0, 1, 0, 0, 1, 0, 1], [0, 0, 0, 16, 16, 16, 16, 0]);
212	  }
213	}
