215	export function buildChunkMesh(gl: WebGL2RenderingContext, world: World, rocks: BlockRegistry, cx: number, cz: number): ChunkMesh {
216	  const chunk = world.chunkAt(cx, cz);
217	  if (!chunk) return { solid: null, translucent: null };
218	  const solid = new Builder();
219	  const trans = new Builder();
220	  const baseX = cx * 16, baseZ = cz * 16;
221	
222	  for (let y = WORLD_MIN_Y; y < WORLD_MAX_Y; y++) {
223	    for (let lz = 0; lz < 16; lz++) {
224	      for (let lx = 0; lx < 16; lx++) {
225	        const x = baseX + lx, z = baseZ + lz;
226	        const id = chunk.blocks[world.idx(x, y, z)];
227	        if (id === 0) continue;
228	        const def = rocks.get(id);
229	        if (!def.flags) continue;
230	        const target = rocks.translucent[id] ? trans : solid;
231	        if (def.custom) {
232	          emitFluid(target, world, rocks, x, y, z, id, def);
233	          continue;
234	        }
235	        for (const q of def.quads) {
236	          if (isCulled(world, rocks, x, y, z, id, q)) continue;
