// Software block-icon renderer for GUI slots.
import type { LoadedAssets } from './assets.js';
import type { BlockDef, Quad } from './blocks.js';

const SIZE = 64;
const CENTER = SIZE / 2;
const CONTENT = 56;
const SHADE = [0.45, 1, 0.72, 0.82, 0.64, 0.55];

type Vec2 = [number, number];

interface ScreenQuad { quad: Quad; pts: Vec2[]; depth: number; }

export class BlockIconRenderer {
  private layerKey = new Map<number, string>();
  private variants = new Map<string, HTMLCanvasElement>();
  constructor(private assets: LoadedAssets) {
    for (const [key, tex] of Object.entries(assets.manifest.textures)) {
      if (tex.arrayLayer >= 0) this.layerKey.set(tex.arrayLayer, key);
    }
  }

  render(def: BlockDef): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = SIZE; canvas.height = SIZE;
    const ctx = canvas.getContext('2d')!;
    ctx.imageSmoothingEnabled = false;

    if (isCross(def)) { this.drawSprite(ctx, def, 0,0,SIZE,SIZE); return canvas; }

    const drawable = def.quads.filter(q => this.layerKey.has(q.layer));
    if (!drawable.length) { this.drawFallback(ctx, def); return canvas; }

    const projected = drawable.map(q => this.projectQuad(q));
    // compute bounds from pts
    ...
    const scale = CONTENT / Math.max(w,h, 1e-6);
    const ox = CENTER - ((minX+maxX)/2)*scale, oy = ...
    // transform points
    for each quad pts: sx = ox + x*scale, sy = oy + y*scale
    // sort by depth descending
    ...
    for q of sorted: this.drawTexturedQuad(ctx, q, tint, shade, def)
    return canvas;
  }
}
