private tinted(key: string, color: string): HTMLCanvasElement | null {
  const cacheKey = key + '|' + color;
  const cached = this.iconCache.get(cacheKey);
  if (cached) return cached;
  const img = this.assets.icons.get(key);
  if (!img) return null;
  const c = document.createElement('canvas');
  c.width = img.width;
  c.height = img.height;
  const ctx = c.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(img, 0, 0);
  ctx.globalCompositeOperation = 'multiply';
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, c.width, c.height);
  this.iconCache.set(cacheKey, c);
  return c;
}

private blockIcon(def: BlockDef): HTMLCanvasElement {
  const cached = this.icons.get(def.id);
  if (cached) return cached;
  const c = document.createElement('canvas');
  c.width = 32;
  c.height = 32;
  const ctx = c.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  const tint = def.name === 'grass_block' ? '#91bd59' :
    def.name === 'oak_leaves' ? '#77ab2f' :
      def.name === 'birch_leaves' ? '#80a755' :
        def.name === 'spruce_leaves' ? '#619961' : null;
  const top = def.iconTop ? (tint ? this.tinted(def.iconTop, tint) : this.assets.icons.get(def.iconTop)) : null;
  const side = def.iconSide ? (tint ? this.tinted(def.iconSide, tint) : this.assets.icons.get(def.iconSide)) : null;
  const flat = ['short_grass', 'fern', 'dead_bush', 'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy',
    'allium', 'lily_of_the_valley', 'torch', 'lantern', 'cactus', 'sulfur_spike', 'water', 'lava'].includes(def.name);
  const cube = !flat && !!top && !!side;
  if (cube && top && side) {
    ctx.save();
    ctx.setTransform(1, 0.5, -1, 0.5, 16, 0);
    ctx.drawImage(top as CanvasImageSource, 0, 0);
    ctx.restore();
    ctx.save();
    ctx.filter = 'brightness(80%)';
    ctx.setTransform(1, 0.5, 0, 1, 0, 8);
    ctx.drawImage(side as CanvasImageSource, 0, 0);
    ctx.restore();
    ctx.save();
    ctx.filter = 'brightness(60%)';
    ctx.setTransform(1, -0.5, 0, 1, 16, 16);
    ctx.drawImage(side as CanvasImageSource, 0, 0);
    ctx.restore();
  } else {
    const flatImg = this.assets.icons.get(def.iconFlat ?? '');
    if (flatImg) ctx.drawImage(flatImg, 0, 0, 32, 32);
    else if (top) ctx.drawImage(top as CanvasImageSource, 0, 0, 32, 32);
  }
  this.icons.set(def.id, c);
  return c;
}

