    addBox(-0.085, -0.68, -0.075, 0.085, -0.5, 0.075, [0.70, 0.52, 0.40]);
    addBox(-0.085, -0.56, -0.075, 0.085, 0.08, 0.075, [0.72, 0.54, 0.42]);
