1	export class ShaderProgram {
2	  program: WebGLProgram;
3	  uniforms: Record<string, WebGLUniformLocation | null> = {};
4	  constructor(private gl: WebGL2RenderingContext, vsSource: string, fsSource: string) {
5	    const vs = compile(gl, gl.VERTEX_SHADER, vsSource);
6	    const fs = compile(gl, gl.FRAGMENT_SHADER, fsSource);
7	    const p = gl.createProgram()!;
8	    gl.attachShader(p, vs);
9	    gl.attachShader(p, fs);
10	    gl.linkProgram(p);
11	    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
12	      throw new Error('program link failed: ' + gl.getProgramInfoLog(p));
13	    }
14	    gl.deleteShader(vs);
15	    gl.deleteShader(fs);
16	    this.program = p;
17	    const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS) as number;
18	    for (let i = 0; i < n; i++) {
19	      const info = gl.getActiveUniform(p, i)!;
20	      const name = info.name.replace(/\[0\]$/, '');
21	      this.uniforms[name] = gl.getUniformLocation(p, info.name);
22	    }
23	  }
