1	// Software-rasterized vanilla-style GUI block icons from baked quad geometry.
2	import type { LoadedAssets } from './assets.js';
3	import type { BlockDef, Quad } from './blocks.js';
4	
5	const SIZE = 64;
6	const HALF = SIZE / 2;
7	const FIT = 56;
8	const ROT_X = (30 * Math.PI) / 180;
9	const ROT_Y = (225 * Math.PI) / 180;
10	const CX = Math.cos(ROT_X);
11	const SX = Math.sin(ROT_X);
12	const CY = Math.cos(ROT_Y);
13	const SY = Math.sin(ROT_Y);
14	const FACE_SHADE = [0.45, 1, 0.72, 0.82, 0.64, 0.55];
15	const WHITE: [number, number, number] = [1, 1, 1];
16	const GRASS: [number, number, number] = [145 / 255, 189 / 255, 89 / 255];
17	const FOLIAGE: [number, number, number] = [119 / 255, 171 / 255, 47 / 255];
18	const WATER: [number, number, number] = [63 / 255, 118 / 255, 228 / 255];
19	const TINT_GRASS = 1;
20	const TINT_FOLIAGE = 2;
21	const TINT_WATER = 3;
22	const TINT_FIXED = 4;
23	
24	type Pt = [number, number];
25	
26	interface Face {
27	  q: Quad;
28	  pts: Pt[];
29	  depth: number;
30	  order: number;
31	}
32	
33	function project(x: number, y: number, z: number): [number, number, number] {
34	  const px = x - 0.5, py = y - 0.5, pz = z - 0.5;
35	  const y1 = CX * py - SX * pz;
36	  const z1 = SX * py + CX * pz;
37	  return [CY * px + SY * z1, -y1, -SY * px + CY * z1];
38	}
39	
40	function isCrossShape(def: BlockDef): boolean {
41	  if (def.quads.length !== 4) return false;
42	  for (const q of def.quads) if (q.d < 2 || q.d > 5) return false;
43	  return true;
44	}
45	
46	export class BlockIconRenderer {
47	  private layerKeys = new Map<number, string>();
48	  private textures = new Map<string, HTMLCanvasElement>();
49	
50	  constructor(private assets: LoadedAssets) {
51	    for (const [key, tex] of Object.entries(assets.manifest.textures)) {
52	      if (tex.arrayLayer >= 0) this.layerKeys.set(tex.arrayLayer, key);
53	    }
54	  }
55	
56	  render(def: BlockDef): HTMLCanvasElement {
57	    const canvas = document.createElement('canvas');
58	    canvas.width = SIZE;
59	    canvas.height = SIZE;
60	    const ctx = canvas.getContext('2d')!;
61	    ctx.imageSmoothingEnabled = false;
62	
63	    if (isCrossShape(def)) {
64	      this.drawFlat(ctx, def);
65	      return canvas;
66	    }
67	
68	    const faces: Face[] = [];
69	    for (const q of def.quads) {
70	      const key = this.layerKeys.get(q.layer);
71	      if (q.p.length < 12 || !key || !this.assets.icons.has(key)) continue;
72	      const pts: Pt[] = [];
73	      let depth = 0;
74	      for (let i = 0; i < 4; i++) {
75	        const [x, y, z] = project(q.p[i * 3], q.p[i * 3 + 1], q.p[i * 3 + 2]);
76	        pts.push([x, y]);
77	        depth += z;
78	      }
79	      faces.push({ q, pts, depth: depth / 4, order: faces.length });
80	    }
81	    if (faces.length === 0) {
82	      this.drawFallback(ctx, def);
83	      return canvas;
84	    }
85	
86	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
87	    for (const f of faces) {
88	      for (const [x, y] of f.pts) {
89	        if (x < minX) minX = x;
90	        if (x > maxX) maxX = x;
91	        if (y < minY) minY = y;
92	        if (y > maxY) maxY = y;
93	      }
94	    }
95	    const span = Math.max(maxX - minX, maxY - minY, 1e-6);
96	    const scale = FIT / span;
97	    const ox = HALF - ((minX + maxX) / 2) * scale;
98	    const oy = HALF - ((minY + maxY) / 2) * scale;
99	    for (const f of faces) {
100	      for (const p of f.pts) {
101	        p[0] = ox + p[0] * scale;
102	        p[1] = oy + p[1] * scale;
103	      }
104	    }
105	    faces.sort((a, b) => (b.depth - a.depth) || (a.order - b.order));
106	
107	    for (const f of faces) {
108	      const key = this.layerKeys.get(f.q.layer);
109	      if (!key) continue;
110	      const tint = this.tintFor(def, f.q.ti);
